import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import type { ProjectType } from '~/client';

export const projectSchemaObject = {
  name: z
    .string({ message: 'Project Name is required' })
    .trim()
    .nonempty({ message: 'Project Name is required' })
    .max(255, { message: 'Project Name must be at most 255 characters long' }),
  short_description: z
    .string({ message: 'Short Project Description is required' })
    .trim()
    .nonempty({ message: 'Short Project Description is required' })
    .max(255, { message: 'Short Project Description must be at most 255 characters long' }),
  description: z
    .string({ message: 'Project Description is required' })
    .trim()
    .nonempty({ message: 'Project Description is required' })
    .max(10000, { message: 'Project Description must be at most 10000 characters long' }),
  date_range: z
    .object(
      {
        start: z.string().trim().nonempty({ message: 'Start date is required' }),
        end: z.string().trim().nonempty({ message: 'End date is required' }),
      },
      {
        message: 'Date range is required',
      }
    )
    .refine(
      (data) => {
        return Boolean(data.start) && Boolean(data.end);
      },
      {
        message: 'Date range is required',
      }
    ),
  client: z
    .string({ message: 'Client is required' })
    .trim()
    .nonempty({ message: 'Client is required' })
    .max(255, { message: 'Client must be at most 255 characters long' }),
  type: z.string({ message: 'Project Type is required' }).transform((value) => value as ProjectType),
  time_zone: z.string({ message: 'Project Time Zone is required' }),
  regions: z
    .record(
      z.string(),
      z.object({
        name: z
          .string({ message: 'Region name is required' })
          .trim()
          .nonempty({ message: 'Region name is required' })
          .max(255, {
            message: 'Region name must be at most 255 characters long',
          }),
        signatures_goal: z.preprocess(
          (val) => {
            if (val === '' || val === null || val === undefined) {
              return undefined;
            }
            val = String(val).trim().replaceAll(',', '');
            if (typeof val === 'string') {
              const parsed = Number(val);
              return isNaN(parsed) ? val : parsed;
            }
            return Number(val);
          },
          z
            .number({
              required_error: 'Signatures goal is required',
              invalid_type_error: 'Signatures goal must be a number',
            })
            .int({ message: 'Signatures goal must be an integer' })
            .optional()
        ),
      }),
      {
        message: 'At least one region is required',
      }
    )
    .optional(),
  location_fips_codes: z.array(z.string()).nullable().optional(),
};

export const formSchema = toTypedSchema(z.object(projectSchemaObject));
