<template>
  <Dialog v-if="!isMobile" :open="open" @update:open="onOpenChange">
    <DialogContent
      class="max-w-[720px] w-[95vw] max-h-[80vh] h-[80vh] p-0 gap-0 flex flex-col overflow-hidden"
      @escape-key-down="onCloseAttempt('escape', $event)"
      @interact-outside="onCloseAttempt('outside', $event)"
    >
      <DialogHeader class="px-6 pt-6 pb-3 gap-3 shrink-0">
        <DialogTitle class="text-xl">Select counties</DialogTitle>
        <div class="flex items-center gap-2">
          <div ref="desktopSearchWrapRef" class="relative flex-1">
            <Input
              v-model="searchInput"
              type="text"
              class="pr-9"
              placeholder="Search by county, state code, or FIPS"
              aria-label="Search counties"
              :disabled="viewMode === 'selected'"
              @update:model-value="updateSearch"
              @keydown.enter.prevent="onSearchEnter"
              @keydown.escape="onSearchEscape"
              @keydown.down="onSearchArrowDown"
            />
            <button
              v-if="searchInput"
              type="button"
              class="absolute top-1/2 right-2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
              aria-label="Clear search"
              @click="clearSearch"
            >
              <X class="h-4 w-4" />
            </button>
          </div>
          <Button v-if="draft.size > 0" variant="ghost" size="sm" class="shrink-0" @click="onToggleViewMode">
            {{ viewMode === 'selected' ? 'Browse' : `Selected (${draft.size})` }}
          </Button>
        </div>
      </DialogHeader>

      <div class="flex-1 min-h-0 grid grid-cols-[260px_1fr] border-t">
        <template v-if="isLoading">
          <div class="col-span-2 flex items-center justify-center">
            <AppLoader subject="counties" variant="inline" />
          </div>
        </template>
        <template v-else-if="error">
          <div class="col-span-2 flex items-center justify-center">
            <AppError
              :error="error"
              title="Failed to load counties"
              variant="table"
              :action="onRetry"
              action-text="Retry"
            />
          </div>
        </template>
        <template v-else>
          <div class="border-r overflow-hidden">
            <FipsStateList
              :states="states"
              :active-state="activeState"
              :selected-count-by-state="selectedCountByState"
              :total-by-state="totalByState"
              :mode="mode"
              :match-count-by-state="matchCountByState"
              :state-name-matches-search="stateNameMatchesSearch"
              @activate="onActivateStateDesktop"
              @bulk-toggle="onBulkToggleState"
            />
          </div>
          <div class="overflow-hidden flex flex-col">
            <template v-if="viewMode === 'selected'">
              <FipsSelectedView
                :selected="draft"
                :all-counties="allCounties"
                :total-by-state="totalByState"
                @toggle="onToggleCounty"
              />
            </template>
            <FipsCountyResultPane
              v-else
              :mode="mode"
              :active-state="activeState"
              :enter-intent="enterIntent"
              :visible-counties="visibleCounties"
              :selected="draft"
              :query="searchInput"
              @toggle="onToggleCounty"
            />
          </div>
        </template>
      </div>

      <DialogFooter class="px-6 py-4 border-t shrink-0">
        <Button variant="outline" @click="onCloseAttempt('cancel', null)">Cancel</Button>
        <Button :disabled="isLoading" @click="onSave">Save</Button>
      </DialogFooter>

      <FipsDiscardConfirm
        v-if="confirmDiscardOpen"
        :count="pendingDiscardDiff"
        @cancel="confirmDiscardOpen = false"
        @discard="onDiscardConfirmed"
      />
    </DialogContent>
  </Dialog>

  <Sheet v-else :open="open" @update:open="onOpenChange">
    <SheetContent
      side="bottom"
      class="h-[90vh] p-0 gap-0 flex flex-col overflow-hidden"
      @escape-key-down="onCloseAttempt('escape', $event)"
      @interact-outside="onCloseAttempt('outside', $event)"
    >
      <SheetHeader class="px-4 pt-6 pb-3 gap-3 shrink-0">
        <div class="flex items-center gap-2">
          <Button
            v-if="mobileView === 'county' && mode === 'browse'"
            variant="ghost"
            size="icon"
            aria-label="Back to states"
            class="h-8 w-8 shrink-0"
            @click="onMobileBack"
          >
            <ChevronLeft class="h-5 w-5" />
          </Button>
          <SheetTitle class="text-xl">
            {{
              mobileView === 'county' && mode === 'browse' && activeState ? stateName(activeState) : 'Select counties'
            }}
          </SheetTitle>
        </div>
        <div class="flex items-center gap-2">
          <div ref="mobileSearchWrapRef" class="relative flex-1">
            <Input
              v-model="searchInput"
              type="text"
              class="pr-9"
              placeholder="Search by county, state code, or FIPS"
              aria-label="Search counties"
              :disabled="viewMode === 'selected'"
              @update:model-value="updateSearch"
              @keydown.enter.prevent="onSearchEnter"
              @keydown.escape="onSearchEscape"
              @keydown.down="onSearchArrowDown"
            />
            <button
              v-if="searchInput"
              type="button"
              class="absolute top-1/2 right-2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
              aria-label="Clear search"
              @click="clearSearch"
            >
              <X class="h-4 w-4" />
            </button>
          </div>
          <Button v-if="draft.size > 0" variant="ghost" size="sm" class="shrink-0" @click="onToggleViewMode">
            {{ viewMode === 'selected' ? 'Browse' : `Selected (${draft.size})` }}
          </Button>
        </div>
      </SheetHeader>

      <div class="flex-1 min-h-0 border-t">
        <template v-if="isLoading">
          <div class="h-full flex items-center justify-center">
            <AppLoader subject="counties" variant="inline" />
          </div>
        </template>
        <template v-else-if="error">
          <div class="h-full flex items-center justify-center">
            <AppError
              :error="error"
              title="Failed to load counties"
              variant="table"
              :action="onRetry"
              action-text="Retry"
            />
          </div>
        </template>
        <template v-else-if="viewMode === 'selected'">
          <FipsSelectedView
            :selected="draft"
            :all-counties="allCounties"
            :total-by-state="totalByState"
            @toggle="onToggleCounty"
          />
        </template>
        <template v-else>
          <div v-show="mobileView === 'state' && mode === 'browse'" class="h-full overflow-hidden">
            <FipsStateList
              :states="states"
              :active-state="activeState"
              :selected-count-by-state="selectedCountByState"
              :total-by-state="totalByState"
              :mode="mode"
              :match-count-by-state="matchCountByState"
              :state-name-matches-search="stateNameMatchesSearch"
              @activate="onMobileActivateState"
              @bulk-toggle="onBulkToggleState"
            />
          </div>
          <div v-show="mobileView === 'county' || mode === 'search'" class="h-full overflow-hidden flex flex-col">
            <FipsCountyResultPane
              :mode="mode"
              :active-state="activeState"
              :enter-intent="enterIntent"
              :visible-counties="visibleCounties"
              :selected="draft"
              :query="searchInput"
              @toggle="onToggleCounty"
            />
          </div>
        </template>
      </div>

      <SheetFooter class="px-4 py-4 border-t shrink-0 flex-row justify-end gap-2">
        <Button variant="outline" @click="onCloseAttempt('cancel', null)">Cancel</Button>
        <Button :disabled="isLoading" @click="onSave">Save</Button>
      </SheetFooter>

      <FipsDiscardConfirm
        v-if="confirmDiscardOpen"
        :count="pendingDiscardDiff"
        @cancel="confirmDiscardOpen = false"
        @discard="onDiscardConfirmed"
      />
    </SheetContent>
  </Sheet>
</template>

<script setup lang="ts">
import { useDebounceFn, useWindowSize } from '@vueuse/core';
import { ChevronLeft, X } from 'lucide-vue-next';
import { stateName } from '~/constants/usStates';
import { MOBILE_BREAKPOINT_PX } from '~/constants/breakpoints';
import type { FipsCountyCentroid } from '~/client';

interface Props {
  initialSelection: string[];
  counties: FipsCountyCentroid[];
  isLoading: boolean;
  error: Error | null;
}

const props = defineProps<Props>();

const emit = defineEmits<{
  save: [selection: string[]];
  retry: [];
}>();

const open = defineModel<boolean>('open', { default: false });

const allCounties = computed(() => props.counties);

// Keep unknown FIPS codes in the draft so they survive a Save - we just can't render them anywhere.
const draft = ref<Set<string>>(new Set(props.initialSelection));
const activeState = ref<string | null>(null);
const search = ref('');
const searchInput = ref('');
const confirmDiscardOpen = ref(false);
const pendingDiscardDiff = ref(0);

const viewMode = ref<'browse' | 'selected'>('browse');

watch(
  () => draft.value.size,
  (size) => {
    if (size === 0 && viewMode.value === 'selected') viewMode.value = 'browse';
  }
);

// shadcn Input doesn't expose its DOM node, so we ref the wrapper and grab the <input> via querySelector.
const desktopSearchWrapRef = useTemplateRef<HTMLElement>('desktopSearchWrapRef');
const mobileSearchWrapRef = useTemplateRef<HTMLElement>('mobileSearchWrapRef');

function refocusSearchInput() {
  nextTick(() => {
    const wrap = desktopSearchWrapRef.value ?? mobileSearchWrapRef.value;
    wrap?.querySelector('input')?.focus();
  });
}

const { width } = useWindowSize();
// Captured per open (in resetOnOpen), not live: swapping the Dialog/Sheet variant mid-open
// unmounts one library's modal under the other's confirm overlay and the page ends up click-dead.
const isMobile = ref(width.value < MOBILE_BREAKPOINT_PX);

const mobileView = ref<'state' | 'county'>('state');

function normalize(s: string): string {
  return s
    .toLowerCase()
    .replace(/[^a-z0-9 ]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

const updateSearch = useDebounceFn((value: string | number) => {
  search.value = normalize(String(value));
}, 150);

// Reset draft/search/view to the current selection every time the dialog OPENS (not on close).
// The open is always parent-driven (no DialogTrigger here), so Reka never emits update:open(true)
// for us to hook - watch the model's false->true edge instead.
function resetOnOpen() {
  isMobile.value = width.value < MOBILE_BREAKPOINT_PX;
  draft.value = new Set(props.initialSelection);
  searchInput.value = '';
  search.value = '';
  confirmDiscardOpen.value = false;
  mobileView.value = 'state';
  viewMode.value = 'browse';
  const firstSelected = props.initialSelection
    .map((fips) => countyByFips.value.get(fips)?.state_code)
    .find((code): code is string => !!code);
  activeState.value = firstSelected ?? null;
}

watch(open, (isOpen, wasOpen) => {
  if (isOpen && !wasOpen) resetOnOpen();
});

const countyByFips = computed<Map<string, FipsCountyCentroid>>(() => {
  const m = new Map<string, FipsCountyCentroid>();
  for (const c of allCounties.value) m.set(c.fips_code, c);
  return m;
});

const states = computed(() => [...new Set(allCounties.value.map((c) => c.state_code))]);

const totalByState = computed<Map<string, number>>(() => {
  const m = new Map<string, number>();
  for (const c of allCounties.value) m.set(c.state_code, (m.get(c.state_code) ?? 0) + 1);
  return m;
});

const selectedCountByState = computed<Map<string, number>>(() => {
  const m = new Map<string, number>();
  for (const fips of draft.value) {
    const c = countyByFips.value.get(fips);
    if (c) m.set(c.state_code, (m.get(c.state_code) ?? 0) + 1);
  }
  return m;
});

const mode = computed<'browse' | 'search'>(() => (search.value ? 'search' : 'browse'));

function matchesSearchGlobal(c: FipsCountyCentroid, q: string): boolean {
  const name = normalize(c.county_name);
  const sname = normalize(stateName(c.state_code));
  const scode = c.state_code.toLowerCase();
  return name.includes(q) || sname.includes(q) || scode.includes(q) || c.fips_code.includes(q);
}

function rankMatch(c: FipsCountyCentroid, q: string): number {
  const name = normalize(c.county_name);
  if (name.startsWith(q)) return 0;
  if (name.includes(q)) return 1;
  if (/^\d+$/.test(q) && c.fips_code.startsWith(q)) return 2;
  // Exact state-code search (e.g. "tx") should surface that state's counties near the top.
  if (c.state_code.toLowerCase() === q) return 3;
  const sname = normalize(stateName(c.state_code));
  if (sname.startsWith(q)) return 4;
  if (sname.includes(q)) return 5;
  return 6;
}

function rankMatches(arr: FipsCountyCentroid[], q: string): FipsCountyCentroid[] {
  return [...arr].sort((a, b) => {
    const r = rankMatch(a, q) - rankMatch(b, q);
    if (r !== 0) return r;
    return a.county_name.localeCompare(b.county_name);
  });
}

const visibleCounties = computed<FipsCountyCentroid[]>(() => {
  if (mode.value === 'search') {
    const q = search.value;
    const matches = allCounties.value.filter((c) => matchesSearchGlobal(c, q));
    return rankMatches(matches, q);
  }
  return activeState.value ? allCounties.value.filter((c) => c.state_code === activeState.value) : [];
});

const matchCountByState = computed<Map<string, number>>(() => {
  const m = new Map<string, number>();
  if (mode.value !== 'search') return m;
  const q = search.value;
  // Only county name + FIPS matches here. State-name matches are handled separately,
  // otherwise typing "utah" while Utah is active would show "29 matches" which is misleading.
  for (const c of allCounties.value) {
    if (normalize(c.county_name).includes(q) || c.fips_code.includes(q)) {
      m.set(c.state_code, (m.get(c.state_code) ?? 0) + 1);
    }
  }
  return m;
});

const stateNameMatchesSearch = computed<Set<string>>(() => {
  const s = new Set<string>();
  if (mode.value !== 'search') return s;
  const q = search.value;
  if (!q) return s;
  for (const code of states.value) {
    if (code.toLowerCase() === q) {
      s.add(code);
      continue;
    }
    const tokens = normalize(stateName(code)).split(' ');
    if (tokens.some((t) => t.startsWith(q))) {
      s.add(code);
    }
  }
  return s;
});

function detectStateExactMatch(q: string): string | null {
  for (const code of states.value) {
    if (code.toLowerCase() === q || normalize(stateName(code)) === q) {
      return code;
    }
  }
  return null;
}

const stateByFipsPrefix = computed<Map<string, string>>(() => {
  const m = new Map<string, string>();
  for (const c of allCounties.value) {
    const prefix = c.fips_code.slice(0, 2);
    if (!m.has(prefix)) m.set(prefix, c.state_code);
  }
  return m;
});

function detectStateFipsPrefix(q: string): string | null {
  if (!/^\d{2}$/.test(q)) return null;
  return stateByFipsPrefix.value.get(q) ?? null;
}

interface EnterIntentCounty {
  type: 'county';
  county: FipsCountyCentroid;
  selected: boolean;
}
interface EnterIntentBulk {
  type: 'bulk';
  stateCode: string;
  count: number;
  selected: boolean;
}
type EnterIntent = EnterIntentCounty | EnterIntentBulk | null;

function stateFullySelected(stateCode: string): boolean {
  const total = totalByState.value.get(stateCode) ?? 0;
  return total > 0 && (selectedCountByState.value.get(stateCode) ?? 0) >= total;
}

// Pass the live input (not the debounced `search`) so a fast typist's Enter isn't a no-op against stale state.
function resolveEnterIntent(rawQuery: string): EnterIntent {
  const q = normalize(rawQuery);
  if (!q) return null;

  const matches = allCounties.value.filter((c) => matchesSearchGlobal(c, q));
  const first = rankMatches(matches, q)[0];
  if (first) {
    const r = rankMatch(first, q);
    if (r === 0 || r === 1) {
      return { type: 'county', county: first, selected: draft.value.has(first.fips_code) };
    }
  }

  const statePrefix = detectStateFipsPrefix(q);
  if (statePrefix) {
    return {
      type: 'bulk',
      stateCode: statePrefix,
      count: totalByState.value.get(statePrefix) ?? 0,
      selected: stateFullySelected(statePrefix),
    };
  }

  const stateExact = detectStateExactMatch(q);
  if (stateExact) {
    return {
      type: 'bulk',
      stateCode: stateExact,
      count: totalByState.value.get(stateExact) ?? 0,
      selected: stateFullySelected(stateExact),
    };
  }

  if (first && matches.length === 1) {
    return { type: 'county', county: first, selected: draft.value.has(first.fips_code) };
  }

  return null;
}

// Drives the banner, so it tracks the debounced `search` to avoid flicker while typing.
const enterIntent = computed<EnterIntent>(() => {
  if (mode.value !== 'search') return null;
  return resolveEnterIntent(search.value);
});

function computeDiff(): number {
  const original = new Set(props.initialSelection);
  let diff = 0;
  for (const fips of draft.value) {
    if (!original.has(fips)) diff += 1;
  }
  for (const fips of original) {
    if (!draft.value.has(fips)) diff += 1;
  }
  return diff;
}

function onToggleCounty(fips: string) {
  const next = new Set(draft.value);
  if (next.has(fips)) next.delete(fips);
  else next.add(fips);
  draft.value = next;
}

function onActivateStateDesktop(stateCode: string) {
  activeState.value = stateCode;
  refocusSearchInput();
}

function onMobileActivateState(stateCode: string) {
  activeState.value = stateCode;
  mobileView.value = 'county';
  refocusSearchInput();
}

function onMobileBack() {
  mobileView.value = 'state';
  refocusSearchInput();
}

function bulkToggleState(stateCode: string) {
  const stateCounties = allCounties.value.filter((c) => c.state_code === stateCode);
  if (stateCounties.length === 0) return;
  const next = new Set(draft.value);
  const allSelected = stateCounties.every((c) => next.has(c.fips_code));
  if (allSelected) {
    for (const c of stateCounties) next.delete(c.fips_code);
  } else {
    for (const c of stateCounties) next.add(c.fips_code);
  }
  draft.value = next;
}

function onBulkToggleState(stateCode: string, origin: 'keyboard' | 'pointer') {
  bulkToggleState(stateCode);
  // Keyboard bulk-toggle stays in the state list so Shift+Enter -> arrow -> Shift+Enter works, as aria-keyshortcuts promises.
  if (origin !== 'keyboard') refocusSearchInput();
}

function tryClose(reason: 'escape' | 'outside' | 'cancel') {
  if (reason === 'escape' && search.value) {
    searchInput.value = '';
    search.value = '';
    return;
  }
  const diff = computeDiff();
  if (diff >= 1) {
    pendingDiscardDiff.value = diff;
    confirmDiscardOpen.value = true;
    return;
  }
  open.value = false;
}

// ESC / outside-click come in as cancelable Reka events. Always preventDefault so Reka's internal
// close doesn't ALSO fire onOpenChange(false) - tryClose owns the single state write.
function onCloseAttempt(reason: 'escape' | 'outside' | 'cancel', event: Event | null) {
  if (event && 'preventDefault' in event) event.preventDefault();
  tryClose(reason);
}

function onOpenChange(value: boolean) {
  if (value) {
    open.value = true;
    return;
  }
  // The built-in close X routes here (it has no cancelable event to intercept), so guard it too.
  tryClose('cancel');
}

function onDiscardConfirmed() {
  confirmDiscardOpen.value = false;
  open.value = false;
}

function onSave() {
  // Sort so the parent's dirty-check (isEqual against a sorted baseline) doesn't churn on reorder.
  emit('save', [...draft.value].sort());
}

function onRetry() {
  emit('retry');
}

function onSearchEnter() {
  const intent = resolveEnterIntent(searchInput.value);
  if (!intent) return;
  if (intent.type === 'county') {
    onToggleCounty(intent.county.fips_code);
  } else {
    bulkToggleState(intent.stateCode);
  }
}

function clearSearch() {
  searchInput.value = '';
  search.value = '';
}

function onSearchEscape(event: KeyboardEvent) {
  if (searchInput.value) {
    event.preventDefault();
    event.stopPropagation();
    clearSearch();
  }
}

function onToggleViewMode() {
  viewMode.value = viewMode.value === 'selected' ? 'browse' : 'selected';
}

// Roving-tabindex lists: jump to whichever option is currently highlighted (or the first if none).
function focusFirstOption(listboxSelector: string): boolean {
  const listbox = document.querySelector<HTMLElement>(listboxSelector);
  if (!listbox) return false;
  const target =
    listbox.querySelector<HTMLElement>('[role="option"][tabindex="0"]') ??
    listbox.querySelector<HTMLElement>('[role="option"]');
  if (!target) return false;
  target.focus();
  return true;
}

// focus the container, not an item - reka highlights the first item itself; item focus leaves its highlight unset
function focusCountyListbox(): boolean {
  const listbox = document.querySelector<HTMLElement>('[data-listbox-counties]');
  if (!listbox) return false;
  listbox.focus();
  return true;
}

// ArrowDown from search lands on whichever pane is actually visible: the state list when we're browsing
// states (no county pane yet), otherwise the county list.
function onSearchArrowDown(event: KeyboardEvent) {
  if (viewMode.value === 'selected') return;

  const targetsStateList = isMobile.value
    ? mobileView.value === 'state' && mode.value === 'browse'
    : mode.value === 'browse' && !activeState.value;

  const moved = targetsStateList ? focusFirstOption('[data-listbox-states]') : focusCountyListbox();

  if (moved) event.preventDefault();
}
</script>
