<template>
  <ListboxRoot class="h-full" :multiple="true" :model-value="selectedArray" @update:model-value="onModelValueChange">
    <!-- ListboxContent carries reka's keyboard nav - Root > Virtualizer alone has none -->
    <ListboxContent
      class="relative flex h-full flex-col overflow-y-auto outline-none"
      aria-label="Counties"
      data-listbox-counties
    >
      <ListboxVirtualizer
        v-slot="{ option }"
        :options="counties"
        :estimate-size="36"
        :overscan="8"
        :text-content="countyTextContent"
      >
        <ListboxItem
          :value="option.fips_code"
          class="flex w-full items-center gap-2 px-3 py-2 text-left text-sm hover:bg-accent data-[highlighted]:bg-accent transition-colors cursor-pointer"
        >
          <Checkbox :model-value="selected.has(option.fips_code)" :tabindex="-1" class="pointer-events-none" />
          <span class="truncate flex-1">{{ option.county_name }}, {{ option.state_code }}</span>
          <span class="ml-auto text-xs text-muted-foreground shrink-0 font-mono">{{ option.fips_code }}</span>
        </ListboxItem>
      </ListboxVirtualizer>
    </ListboxContent>
  </ListboxRoot>
</template>

<script setup lang="ts">
import { ListboxContent, ListboxItem, ListboxRoot, ListboxVirtualizer } from 'reka-ui';
import { Checkbox } from '~/components/ui/checkbox';
import type { FipsCountyCentroid } from '~/client';

interface Props {
  counties: FipsCountyCentroid[];
  selected: Set<string>;
}

const props = defineProps<Props>();

const emit = defineEmits<{
  toggle: [fips: string];
}>();

const selectedArray = computed(() => Array.from(props.selected));

const countyTextContent = (county: FipsCountyCentroid) => county.county_name;

// The virtualizer keeps its scroll offset when the option set swaps (state switch / new search),
// which can leave a short result list rendered below the fold. Reset to the top on every swap.
// ListboxRoot doesn't expose its element, but only one of these is mounted at a time.
watch(
  () => props.counties,
  () => {
    nextTick(() => {
      const el = document.querySelector<HTMLElement>('[data-listbox-counties]');
      if (el) el.scrollTop = 0;
    });
  }
);

// Reka emits the full next array on every change; diff it against our Set to find which one toggled.
function onModelValueChange(next: unknown) {
  const nextArr = Array.isArray(next) ? (next as string[]) : [];
  const currentSet = props.selected;
  const nextSet = new Set(nextArr);

  let changed: string | null = null;
  for (const fips of nextSet) {
    if (!currentSet.has(fips)) {
      changed = fips;
      break;
    }
  }
  if (changed === null) {
    for (const fips of currentSet) {
      if (!nextSet.has(fips)) {
        changed = fips;
        break;
      }
    }
  }
  if (changed !== null) emit('toggle', changed);
}
</script>
