<template>
  <Card class="col-span-8 xl:col-span-5 h-fit">
    <CardHeader>
      <CardTitle>General Information</CardTitle>
    </CardHeader>
    <CardContent class="flex flex-col gap-6">
      <div class="grid grid-cols-1 gap-6 md:grid-cols-2">
        <FormItemWrapper label="Project Name" name="name">
          <template #default="{ slots }">
            <Input id="name" type="text" v-bind="slots.componentField" />
          </template>
        </FormItemWrapper>
        <FormItemWrapper v-if="type === 'create'" label="Project Type" name="type">
          <template #default="{ slots }">
            <KitFormsSelect id="type" :items="projectTypes" :component-field="slots.componentField" />
          </template>
        </FormItemWrapper>
        <div v-if="type === 'edit'" class="flex flex-col gap-3 text-sm">
          <span class="font-medium">Project Type</span>
          <span>{{ projectType ? getProjectTypeLabel(projectType) : '-' }}</span>
        </div>
      </div>
      <FormItemWrapper label="Short Project Description" name="short_description">
        <template #default="{ slots }">
          <Input id="short_description" type="text" v-bind="slots.componentField" />
        </template>
      </FormItemWrapper>
      <FormItemWrapper label="Description" name="description">
        <template #default="{ slots }">
          <Textarea id="description" rows="5" v-bind="slots.componentField" class="resize-none" />
        </template>
      </FormItemWrapper>
      <div class="grid grid-cols-1 md:grid-cols-2 gap-6">
        <FormItemWrapper label="Date Range" name="date_range">
          <template #default="{ slots }">
            <DateRangePicker
              id="date_range"
              v-model:value="dateRangePickerValueComputed"
              v-bind="slots.componentField"
              button-class="w-full"
              @update:value="
                (value) => {
                  if (value.start && value.end) {
                    slots.setValue(
                      {
                        start: value.start?.toString(),
                        end: value.end?.toString(),
                      },
                      false
                    );
                  } else {
                    slots.setValue(undefined, false);
                  }
                }
              "
            />
          </template>
        </FormItemWrapper>
        <FormItemWrapper v-if="type === 'create'" label="Project Time Zone" name="time_zone">
          <template #default="{ slots }">
            <KitFormsSelect
              id="time_zone"
              :items="timezones"
              :component-field="slots.componentField"
              :loading="isLoadingTimezones"
            />
          </template>
        </FormItemWrapper>
        <div v-if="type === 'edit'" class="flex flex-col gap-3 text-sm">
          <span class="font-medium">Project Time Zone</span>
          <span>{{ timezones.find((item) => item.value === projectTimezone)?.name || projectTimezone || '-' }}</span>
        </div>
      </div>
      <div class="grid grid-cols-1 md:grid-cols-2 gap-6">
        <FormItemWrapper label="Client" name="client">
          <template #default="{ slots }">
            <Input id="client" type="text" v-bind="slots.componentField" />
          </template>
        </FormItemWrapper>
        <FormItemWrapper v-if="type === 'edit'" label="Project Status" name="status">
          <template #default="{ slots }">
            <KitFormsSelect id="status" :items="projectsStatus" :component-field="slots.componentField" />
          </template>
        </FormItemWrapper>
      </div>
      <FormItemWrapper label="Project Locations" name="location_fips_codes">
        <template #default="{ slots }">
          <KitFormsFipsCountyPicker :component-field="slots.componentField" />
        </template>
      </FormItemWrapper>
    </CardContent>
  </Card>
</template>

<script lang="ts" setup>
import { projectsStatus } from '~/constants/projects/projectStatusConfig';
import DateRangePicker from '@/components/ui/date-range-picker/DateRangePicker.vue';
import KitFormsSelect from '../kit/forms/KitFormsSelect.vue';
import { projectTypes } from '~/constants/projects/projectTypesConfig';
import type { ProjectType } from '~/client';
import { getProjectTypeLabel } from '~/constants/projects';

interface Props {
  dateRangePickerValue?: any;
  setDateRangePickerValue?: (value: { start?: string; end?: string }) => void;
  type: 'create' | 'edit';
  projectType?: ProjectType | null;
  projectTimezone?: string | undefined;
}

const props = withDefaults(defineProps<Props>(), {
  dateRangePickerValue: undefined,
  setDateRangePickerValue: undefined,
  projectType: null,
  projectTimezone: undefined,
});

const dateRangePickerValueComputed = computed({
  get() {
    return props.dateRangePickerValue;
  },
  set(value) {
    if (props.setDateRangePickerValue) {
      props.setDateRangePickerValue({
        start: value.start ? value.start.toString() : undefined,
        end: value.end ? value.end.toString() : undefined,
      });
    }
  },
});

const { isLoading: isLoadingTimezones, timezones } = useSelectorTimezoneList();
</script>

<style lang="scss" scoped></style>
