<template>
  <div>
    <TooltipProvider :delay-duration="300">
      <Tooltip>
        <TooltipTrigger as-child>
          <div class="relative">
            <Button
              :id="componentField?.name"
              variant="outline"
              class="justify-between h-10 w-full px-3 font-normal"
              :disabled="disabled || isLoading"
              @click.prevent="open = true"
            >
              <span class="truncate">{{ summary }}</span>
              <Spinner v-if="isLoading" class="!w-5 !h-5" />
              <ChevronDown v-else class="ml-6 h-4 w-4 shrink-0 opacity-50" />
            </Button>
            <button
              v-if="currentSelection.length && !disabled && !isLoading"
              type="button"
              class="absolute top-[0.75rem] end-10"
              aria-label="Clear counties"
              @click.stop.prevent="clearSelection"
            >
              <X class="h-4 w-4 shrink-0 opacity-50 hover:opacity-100" />
            </button>
          </div>
        </TooltipTrigger>
        <TooltipContent v-if="fullBreakdown" side="bottom" class="max-w-xs whitespace-pre-line">
          {{ fullBreakdown }}
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
    <p v-if="error" class="p-2 text-sm text-destructive select-none">{{ error.message }}</p>
    <FipsCountyPickerDialog
      v-model:open="open"
      :initial-selection="currentSelection"
      :counties="counties"
      :is-loading="isLoading"
      :error="error"
      @save="onSave"
      @retry="refetch"
    />
  </div>
</template>

<script setup lang="ts">
import type { ComponentFieldBindingObject } from 'vee-validate';
import { ChevronDown, X } from 'lucide-vue-next';
import { useWindowSize } from '@vueuse/core';
import { Spinner } from '~/assets/icons';
import { Button } from '~/components/ui/button';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '~/components/ui/tooltip';
import { fipsBreakdownFull, fipsSummary, fipsSummaryShort } from '~/utils/fipsSummary';

interface Props {
  componentField: ComponentFieldBindingObject;
  disabled?: boolean;
}
const props = withDefaults(defineProps<Props>(), { disabled: false });

const { counties, isLoading, error, refetch } = useSelectorFipsCounties();
const open = ref(false);
const { width } = useWindowSize();

const currentSelection = computed<string[]>(() =>
  Array.isArray(props.componentField?.modelValue) ? props.componentField.modelValue : []
);

const stateCount = computed<number>(() => {
  if (currentSelection.value.length === 0) return 0;
  const codeByFips = new Map<string, string>();
  for (const c of counties.value) codeByFips.set(c.fips_code, c.state_code);
  const set = new Set<string>();
  for (const fips of currentSelection.value) {
    const code = codeByFips.get(fips);
    if (code) set.add(code);
  }
  return set.size;
});

const summary = computed(() =>
  width.value < 360 ? fipsSummaryShort(currentSelection.value) : fipsSummary(currentSelection.value, counties.value)
);

// Only show the tooltip when the trigger label is truncated (4+ states). Below that it's already fully visible.
const fullBreakdown = computed<string>(() => {
  if (stateCount.value < 4) return '';
  return fipsBreakdownFull(currentSelection.value, counties.value);
});

function onSave(selection: string[]) {
  props.componentField?.onChange?.(selection);
  open.value = false;
}

function clearSelection() {
  props.componentField?.onChange?.([]);
}
</script>
