<template>
  <template v-if="mode === 'browse' && !activeState">
    <div class="flex-1 flex items-center justify-center p-6 text-sm text-muted-foreground text-center">
      Type to search across all states, or click a state on the left to browse.
    </div>
  </template>
  <template v-else>
    <div
      v-if="enterIntent"
      class="bg-muted/30 border-b px-3 py-2 text-xs text-muted-foreground flex items-center gap-2"
    >
      <span>Press</span>
      <kbd class="px-1.5 py-0.5 rounded bg-muted text-xs font-mono">Enter</kbd>
      <span v-if="enterIntent.type === 'county'">
        to {{ enterIntent.selected ? 'remove' : 'add' }} {{ enterIntent.county.county_name }},
        {{ enterIntent.county.state_code }}
      </span>
      <span v-else>
        to {{ enterIntent.selected ? 'remove' : 'add' }} all {{ enterIntent.count }} counties in
        {{ stateName(enterIntent.stateCode) }}
      </span>
    </div>
    <div
      v-if="mode === 'search' && visibleCounties.length === 0"
      class="flex flex-col items-center justify-center p-6 text-center text-muted-foreground gap-2"
    >
      <p class="text-sm">No counties match "{{ query }}".</p>
      <p class="text-xs">Try a different query, FIPS code, or state name.</p>
    </div>
    <div v-else class="flex-1 min-h-0 overflow-hidden">
      <FipsCountyList :counties="visibleCounties" :selected="selected" @toggle="emit('toggle', $event)" />
    </div>
  </template>
</template>

<script setup lang="ts">
import { stateName } from '~/constants/usStates';
import type { FipsCountyCentroid } from '~/client';

interface EnterIntentCounty {
  type: 'county';
  county: FipsCountyCentroid;
  selected: boolean;
}
interface EnterIntentBulk {
  type: 'bulk';
  stateCode: string;
  count: number;
  selected: boolean;
}
type EnterIntent = EnterIntentCounty | EnterIntentBulk | null;

interface Props {
  mode: 'browse' | 'search';
  activeState: string | null;
  enterIntent: EnterIntent;
  visibleCounties: FipsCountyCentroid[];
  selected: Set<string>;
  query: string;
}

defineProps<Props>();

const emit = defineEmits<{
  toggle: [fips: string];
}>();
</script>
