<template>
  <!-- Teleported to body so the backdrop covers the whole viewport (an absolute overlay would be
       clipped to the picker's transformed content box). Plain div, not a dialog-library component:
       no focus-scope / dismissable-layer to churn over the picker underneath, which is what caused
       the mobile close loop. Click on the backdrop (self) cancels, matching a normal Dialog. -->
  <Teleport to="body">
    <!-- pointer-events-auto: the open picker is modal and sets body pointer-events:none; without this
         the teleported backdrop (a body sibling, not inside the picker content) would be click-dead. -->
    <div
      class="pointer-events-auto fixed inset-0 z-[60] flex items-center justify-center bg-black/80 p-4 animate-in fade-in-0"
      @click.self="$emit('cancel')"
    >
      <div
        class="relative grid w-full max-w-xs sm:max-w-sm gap-6 rounded-lg border bg-background p-6 shadow-lg animate-in zoom-in-95"
        role="alertdialog"
        aria-modal="true"
        aria-labelledby="fips-discard-title"
      >
        <button
          type="button"
          class="absolute right-4 top-4 rounded-sm opacity-70 ring-offset-background transition-opacity hover:opacity-100 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
          aria-label="Close"
          @click="$emit('cancel')"
        >
          <X class="w-4 h-4" />
        </button>

        <div class="flex flex-col gap-y-2 text-left">
          <h2 id="fips-discard-title" class="text-xl font-semibold leading-none tracking-tight">Discard changes?</h2>
          <p class="font-normal text-base text-accent-foreground w-full">
            You have {{ count }} unsaved changes. Discard them?
          </p>
        </div>

        <div class="flex flex-col-reverse sm:flex-row sm:justify-end sm:gap-x-2">
          <div class="flex flex-wrap justify-end gap-2">
            <Button variant="outline" class="h-10 px-4" @click="$emit('cancel')">Cancel</Button>
            <Button variant="destructive" class="h-10 px-4" @click="$emit('discard')">Discard</Button>
          </div>
        </div>
      </div>
    </div>
  </Teleport>
</template>

<script setup lang="ts">
import { X } from 'lucide-vue-next';

defineProps<{ count: number }>();
defineEmits<{ cancel: []; discard: [] }>();
</script>
