import { getSelectorFipsCounties } from '~/client';
import type { GetSelectorFipsCountiesResponse2 } from '~/client';

export const useSelectorFipsCounties = defineQuery(() => {
  const { data, isLoading, error, refetch } = useQuery({
    key: ['selector-fips-counties-list'],
    query: async (): Promise<GetSelectorFipsCountiesResponse2> => {
      const response = await getSelectorFipsCounties({ composable: '$fetch' });
      // ~3k counties never change within a session, so skip making the array deeply reactive.
      response.items = markRaw(response.items);
      return response;
    },
    staleTime: 24 * 60 * 60 * 1000,
  });

  return {
    counties: computed(() => data.value?.items ?? []),
    isLoading,
    error,
    refetch,
  };
});
