<template>
  <div class="h-full overflow-auto p-2">
    <div v-if="grouped.length === 0" class="p-6 text-center text-sm text-muted-foreground">
      No counties selected yet.
    </div>
    <div v-for="group in grouped" :key="group.stateCode" class="mb-3">
      <h3 class="px-2 py-1.5 text-xs font-semibold text-muted-foreground uppercase tracking-wide">
        {{ stateName(group.stateCode) }} ({{ group.counties.length
        }}<template v-if="(totalByState.get(group.stateCode) ?? 0) > 0">
          / {{ totalByState.get(group.stateCode) }}</template
        >)
      </h3>
      <ul>
        <li
          v-for="c in group.counties"
          :key="c.fips_code"
          class="flex items-center gap-2 px-3 py-2 text-sm hover:bg-accent transition-colors cursor-pointer"
          @click.stop="emit('toggle', c.fips_code)"
        >
          <Checkbox :model-value="true" :tabindex="-1" class="pointer-events-none" />
          <span class="truncate flex-1">{{ c.county_name }}, {{ c.state_code }}</span>
          <span class="ml-auto text-xs text-muted-foreground shrink-0 font-mono">{{ c.fips_code }}</span>
        </li>
      </ul>
    </div>
  </div>
</template>

<script setup lang="ts">
import { Checkbox } from '~/components/ui/checkbox';
import { stateName } from '~/constants/usStates';
import type { FipsCountyCentroid } from '~/client';

interface Props {
  selected: Set<string>;
  allCounties: FipsCountyCentroid[];
  totalByState: Map<string, number>;
}

const props = defineProps<Props>();

const emit = defineEmits<{
  toggle: [fips: string];
}>();

const grouped = computed(() => {
  const countyByFips = new Map<string, FipsCountyCentroid>();
  for (const c of props.allCounties) countyByFips.set(c.fips_code, c);

  const byState = new Map<string, FipsCountyCentroid[]>();
  for (const fips of props.selected) {
    const c = countyByFips.get(fips);
    if (!c) continue;
    if (!byState.has(c.state_code)) byState.set(c.state_code, []);
    byState.get(c.state_code)!.push(c);
  }
  for (const arr of byState.values()) {
    arr.sort((a, b) => a.county_name.localeCompare(b.county_name));
  }
  return [...byState.entries()]
    .map(([stateCode, counties]) => ({ stateCode, counties }))
    .sort((a, b) => stateName(a.stateCode).localeCompare(stateName(b.stateCode)));
});
</script>
