<template>
  <div
    ref="listboxRef"
    class="flex flex-col h-full overflow-y-auto outline-none"
    role="listbox"
    aria-label="States"
    data-listbox-states
    @keydown="onListboxKeydown"
  >
    <div
      v-for="(code, idx) in sortedStates"
      :key="code"
      role="option"
      :tabindex="idx === focusedIdx ? 0 : -1"
      :aria-selected="activeState === code"
      :aria-keyshortcuts="mode === 'browse' ? 'Shift+Enter' : undefined"
      :data-state-code="code"
      :class="
        cn(
          'flex items-center gap-2 px-3 py-2 text-left text-sm border-l-2 border-transparent transition-colors',
          mode === 'browse' &&
            'hover:bg-accent cursor-pointer focus:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring',
          activeState === code && 'bg-accent border-l-primary'
        )
      "
      @click="mode === 'browse' && onRowClick(code, idx)"
    >
      <span
        v-if="mode === 'browse'"
        class="shrink-0 inline-flex items-center justify-center"
        role="presentation"
        @click.stop.prevent="emit('bulkToggle', code, 'pointer')"
      >
        <Checkbox
          :model-value="bulkStateFor(code)"
          :tabindex="-1"
          :aria-label="`Toggle all ${stateName(code)} counties`"
          class="pointer-events-none"
        >
          <Minus v-if="bulkStateFor(code) === 'indeterminate'" class="h-4 w-4" />
          <Check v-else-if="bulkStateFor(code) === true" class="h-4 w-4" />
        </Checkbox>
      </span>
      <span
        :class="
          cn(
            'truncate flex-1',
            mode === 'search' &&
              props.stateNameMatchesSearch?.has(code) &&
              'font-semibold underline decoration-dotted underline-offset-2'
          )
        "
        >{{ stateName(code) }}</span
      >
      <span
        v-if="mode === 'search' && (matchCountByState?.get(code) ?? 0) > 0"
        class="text-xs shrink-0 tabular-nums text-primary font-medium"
      >
        ({{ matchCountByState?.get(code) ?? 0 }} {{ (matchCountByState?.get(code) ?? 0) === 1 ? 'match' : 'matches' }})
      </span>
      <span class="text-xs text-muted-foreground shrink-0">{{ code }}</span>
      <span
        :class="
          cn(
            'text-xs shrink-0 tabular-nums min-w-[64px] text-right',
            (selectedCountByState.get(code) ?? 0) > 0 ? 'font-semibold text-foreground' : 'text-muted-foreground'
          )
        "
      >
        {{ selectedCountByState.get(code) ?? 0 }} / {{ totalByState.get(code) ?? 0 }}
      </span>
    </div>
  </div>
</template>

<script setup lang="ts">
import { Check, Minus } from 'lucide-vue-next';
import { cn } from '@/lib/utils';
import { Checkbox } from '~/components/ui/checkbox';
import { stateName } from '~/constants/usStates';

interface Props {
  states: string[];
  activeState: string | null;
  selectedCountByState: Map<string, number>;
  totalByState: Map<string, number>;
  mode?: 'browse' | 'search';
  matchCountByState?: Map<string, number>;
  stateNameMatchesSearch?: Set<string>;
}

const props = withDefaults(defineProps<Props>(), {
  mode: 'browse',
  matchCountByState: undefined,
  stateNameMatchesSearch: () => new Set<string>(),
});

const emit = defineEmits<{
  activate: [stateCode: string, origin: 'keyboard' | 'pointer'];
  bulkToggle: [stateCode: string, origin: 'keyboard' | 'pointer'];
}>();

const sortedStates = computed(() => [...props.states].sort((a, b) => stateName(a).localeCompare(stateName(b))));

const listboxRef = useTemplateRef<HTMLElement>('listboxRef');

const focusedIdx = ref(0);

watch(
  () => props.activeState,
  (code) => {
    if (!code) return;
    const idx = sortedStates.value.indexOf(code);
    if (idx >= 0) focusedIdx.value = idx;
  },
  { immediate: true }
);

function rowElements(): HTMLElement[] {
  const el = listboxRef.value;
  if (!el) return [];
  return Array.from(el.querySelectorAll<HTMLElement>('[role="option"]'));
}

// Wait a tick so the new tabindex=0 attribute lands before we call focus().
function focusRow(idx: number) {
  const rows = rowElements();
  if (rows.length === 0) return;
  const clamped = Math.max(0, Math.min(idx, rows.length - 1));
  focusedIdx.value = clamped;
  nextTick(() => {
    const refreshed = rowElements();
    refreshed[clamped]?.focus();
  });
}

function onListboxKeydown(e: KeyboardEvent) {
  switch (e.key) {
    case 'ArrowDown':
      e.preventDefault();
      focusRow(focusedIdx.value + 1);
      break;
    case 'ArrowUp':
      e.preventDefault();
      focusRow(focusedIdx.value - 1);
      break;
    case 'Home':
      e.preventDefault();
      focusRow(0);
      break;
    case 'End':
      e.preventDefault();
      focusRow(sortedStates.value.length - 1);
      break;
    case 'Enter':
    case ' ':
      e.preventDefault();
      {
        const code = sortedStates.value[focusedIdx.value];
        if (!code) break;
        // In search mode the rows are inert - activating a state doesn't change the county pane, so it'd just mislead.
        if (props.mode !== 'browse') break;
        // Shift+Enter selects/deselects the whole state without leaving the keyboard.
        if (e.key === 'Enter' && e.shiftKey) emit('bulkToggle', code, 'keyboard');
        else emit('activate', code, 'keyboard');
      }
      break;
  }
}

function onRowClick(code: string, idx: number) {
  focusedIdx.value = idx;
  emit('activate', code, 'pointer');
}

function bulkStateFor(code: string): boolean | 'indeterminate' {
  const selected = props.selectedCountByState.get(code) ?? 0;
  const total = props.totalByState.get(code) ?? 0;
  if (selected === 0) return false;
  if (selected >= total && total > 0) return true;
  return 'indeterminate';
}
</script>
