import type { FipsCountyCentroid } from '~/client';

interface StateSummary {
  state: string;
  count: number;
  total: number;
}

export function fipsSummary(selected: string[], all: FipsCountyCentroid[]): string {
  if (selected.length === 0) return 'Select counties';

  const byState = new Map<string, { count: number; total: number }>();
  const totalsByState = new Map<string, number>();
  const countyByFips = new Map<string, FipsCountyCentroid>();
  for (const c of all) {
    totalsByState.set(c.state_code, (totalsByState.get(c.state_code) ?? 0) + 1);
    countyByFips.set(c.fips_code, c);
  }
  for (const fips of selected) {
    const county = countyByFips.get(fips);
    if (!county) continue;
    const entry = byState.get(county.state_code) ?? {
      count: 0,
      total: totalsByState.get(county.state_code) ?? 0,
    };
    entry.count += 1;
    byState.set(county.state_code, entry);
  }

  const states: StateSummary[] = [...byState.entries()]
    .map(([state, { count, total }]) => ({ state, count, total }))
    .sort((a, b) => b.count - a.count);

  const resolved = states.reduce((sum, s) => sum + s.count, 0);
  const unresolved = selected.length - resolved;
  const noun = resolved === 1 ? 'county' : 'counties';

  if (states.length === 0) {
    const total = selected.length;
    return `${total} ${total === 1 ? 'county' : 'counties'}`;
  }

  const tail = unresolved > 0 ? ` +${unresolved} unresolved` : '';

  if (states.length === 1) {
    const s = states[0];
    if (s.count === s.total || s.count === 1) {
      return `${resolved} ${noun} · ${s.state}${tail}`;
    }
    return `${resolved} ${noun} · ${s.state} ${s.count}${tail}`;
  }

  if (states.length <= 3) {
    const breakdown = states.map((s) => `${s.state} ${s.count}`).join(', ');
    return `${resolved} ${noun} · ${breakdown}${tail}`;
  }

  const top3 = states
    .slice(0, 3)
    .map((s) => `${s.state} ${s.count}`)
    .join(', ');
  const more = states.length - 3;
  const moreNoun = more === 1 ? 'state' : 'states';
  return `${resolved} ${noun} · ${top3} +${more} more ${moreNoun}${tail}`;
}

export function fipsSummaryShort(selected: string[]): string {
  const total = selected.length;
  if (total === 0) return 'Select counties';
  return `${total} ${total === 1 ? 'county' : 'counties'}`;
}

export function fipsBreakdownFull(selected: string[], all: FipsCountyCentroid[]): string {
  if (selected.length === 0) return '';

  const totalsByState = new Map<string, number>();
  const countyByFips = new Map<string, FipsCountyCentroid>();
  for (const c of all) {
    totalsByState.set(c.state_code, (totalsByState.get(c.state_code) ?? 0) + 1);
    countyByFips.set(c.fips_code, c);
  }

  const byState = new Map<string, number>();
  for (const fips of selected) {
    const county = countyByFips.get(fips);
    if (!county) continue;
    byState.set(county.state_code, (byState.get(county.state_code) ?? 0) + 1);
  }

  const rows: StateSummary[] = [...byState.entries()]
    .map(([state, count]) => ({ state, count, total: totalsByState.get(state) ?? 0 }))
    .sort((a, b) => b.count - a.count || a.state.localeCompare(b.state));

  return rows.map((s) => `${s.state}: ${s.count} / ${s.total}`).join('\n');
}
